-- Run with supabase test db; transaction rolls back every adversarial mutation.
begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relrowsecurity), 58::bigint, 'RLS enabled on all public tables through Phase 3D');
select is((select count(*) from pg_policies where schemaname='public' and cmd <> 'SELECT'), 0::bigint, 'No application write policies exist');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='pikas_private' and p.prosecdef and not ('search_path=""'=any(p.proconfig))), 0::bigint, 'Definer helpers pin an empty search path');
select is((select count(*) from pikas_private.role_capabilities where role_code='pos_operator'), 1::bigint, 'POS role has only the narrowly scoped customer lookup capability');
select ok((not has_table_privilege('authenticated','public.accounts','INSERT') and not has_table_privilege('authenticated','public.accounts','UPDATE') and not has_table_privilege('authenticated','public.accounts','DELETE') and not has_table_privilege('authenticated','public.accounts','TRUNCATE')), 'accounts: no direct authenticated mutation privileges');
select ok((not has_table_privilege('anon','public.accounts','SELECT')), 'accounts: anonymous reads denied');
select ok((not has_table_privilege('authenticated','public.schools','INSERT') and not has_table_privilege('authenticated','public.schools','UPDATE') and not has_table_privilege('authenticated','public.schools','DELETE') and not has_table_privilege('authenticated','public.schools','TRUNCATE')), 'schools: no direct authenticated mutation privileges');
select ok((not has_table_privilege('anon','public.schools','SELECT')), 'schools: anonymous reads denied');
select ok((not has_table_privilege('authenticated','public.cafeterias','INSERT') and not has_table_privilege('authenticated','public.cafeterias','UPDATE') and not has_table_privilege('authenticated','public.cafeterias','DELETE') and not has_table_privilege('authenticated','public.cafeterias','TRUNCATE')), 'cafeterias: no direct authenticated mutation privileges');
select ok((not has_table_privilege('anon','public.cafeterias','SELECT')), 'cafeterias: anonymous reads denied');
select ok((not has_table_privilege('authenticated','public.school_locations','INSERT') and not has_table_privilege('authenticated','public.school_locations','UPDATE') and not has_table_privilege('authenticated','public.school_locations','DELETE') and not has_table_privilege('authenticated','public.school_locations','TRUNCATE')), 'school_locations: no direct authenticated mutation privileges');
select ok((not has_table_privilege('anon','public.school_locations','SELECT')), 'school_locations: anonymous reads denied');
select ok((not has_table_privilege('authenticated','public.persons','INSERT') and not has_table_privilege('authenticated','public.persons','UPDATE') and not has_table_privilege('authenticated','public.persons','DELETE') and not has_table_privilege('authenticated','public.persons','TRUNCATE')), 'persons: no direct authenticated mutation privileges');
select ok((not has_table_privilege('anon','public.persons','SELECT')), 'persons: anonymous reads denied');
select ok((not has_table_privilege('authenticated','public.account_memberships','INSERT') and not has_table_privilege('authenticated','public.account_memberships','UPDATE') and not has_table_privilege('authenticated','public.account_memberships','DELETE') and not has_table_privilege('authenticated','public.account_memberships','TRUNCATE')), 'account_memberships: no direct authenticated mutation privileges');
select ok((not has_table_privilege('anon','public.account_memberships','SELECT')), 'account_memberships: anonymous reads denied');
select ok((not has_table_privilege('authenticated','public.school_memberships','INSERT') and not has_table_privilege('authenticated','public.school_memberships','UPDATE') and not has_table_privilege('authenticated','public.school_memberships','DELETE') and not has_table_privilege('authenticated','public.school_memberships','TRUNCATE')), 'school_memberships: no direct authenticated mutation privileges');
select ok((not has_table_privilege('anon','public.school_memberships','SELECT')), 'school_memberships: anonymous reads denied');
select ok((not has_table_privilege('authenticated','public.cafeteria_memberships','INSERT') and not has_table_privilege('authenticated','public.cafeteria_memberships','UPDATE') and not has_table_privilege('authenticated','public.cafeteria_memberships','DELETE') and not has_table_privilege('authenticated','public.cafeteria_memberships','TRUNCATE')), 'cafeteria_memberships: no direct authenticated mutation privileges');
select ok((not has_table_privilege('anon','public.cafeteria_memberships','SELECT')), 'cafeteria_memberships: anonymous reads denied');
select ok((not has_table_privilege('authenticated','public.invitations','INSERT') and not has_table_privilege('authenticated','public.invitations','UPDATE') and not has_table_privilege('authenticated','public.invitations','DELETE') and not has_table_privilege('authenticated','public.invitations','TRUNCATE')), 'invitations: no direct authenticated mutation privileges');
select ok((not has_table_privilege('anon','public.invitations','SELECT')), 'invitations: anonymous reads denied');
select ok((not has_table_privilege('authenticated','public.audit_events','INSERT') and not has_table_privilege('authenticated','public.audit_events','UPDATE') and not has_table_privilege('authenticated','public.audit_events','DELETE') and not has_table_privilege('authenticated','public.audit_events','TRUNCATE')), 'audit_events: no direct authenticated mutation privileges');
select ok((not has_table_privilege('anon','public.audit_events','SELECT')), 'audit_events: anonymous reads denied');
select ok((not has_function_privilege('anon','pikas_private.has_capability(text,uuid,uuid,uuid)','EXECUTE')), 'Anonymous helper execution denied');
select ok((not has_function_privilege('authenticated','pikas_private.audit_foundation_change()','EXECUTE')), 'Audit trigger cannot be called as a client RPC');
select ok((not has_table_privilege('service_role','public.persons','INSERT')), 'Service role is not the provisioning API');
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002001', true);
set local role authenticated;
select is((select count(*) from accounts), 1::bigint, 'Account A admin sees only Account A');
select is((select count(*) from accounts where id='00000000-0000-0000-0000-000000000002'), 0::bigint, 'Account A cannot read Account B');
select is((select count(*) from schools), 2::bigint, 'Explicit account authority sees both own schools');
select is((select count(*) from cafeterias), 3::bigint, 'Explicit account authority sees own structural cafeterias');
select is((select count(*) from school_memberships), 0::bigint, 'Account admin does not inherit school membership administration');
select ok((not pikas_private.has_capability('pos:checkout','00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000111')), 'Account authority does not grant cashier rights');
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002002', true);
set local role authenticated;
select is((select count(*) from schools), 1::bigint, 'School A1 admin sees own school');
select is((select count(*) from schools where id='00000000-0000-0000-0000-000000000012'), 0::bigint, 'Same-account school A2 denied');
select is((select count(*) from schools where id='00000000-0000-0000-0000-000000000021'), 0::bigint, 'Cross-account school B1 denied');
select is((select count(*) from cafeterias), 2::bigint, 'School admin sees cafeterias across both own campuses');
select is((select count(*) from cafeteria_memberships), 0::bigint, 'School Admin has no Cafeteria Admin membership authority');
select is((select count(*) from persons), 6::bigint, 'School Admin sees only persons linked to the authorized school plus self');
select ok((not pikas_private.has_capability('cafeteria:memberships:read','00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000111')), 'Peer domains do not imply one another');
select throws_ok($test$update persons set status='active' where id='00000000-0000-0000-0000-000000001009'$test$, '42501', null, 'Client cannot reactivate another person');
select throws_ok($test$insert into account_memberships(account_id,person_id,role_code) values ('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000001002','account_admin')$test$, '42501', null, 'Client role escalation denied');
select throws_ok($test$update school_memberships set school_id='00000000-0000-0000-0000-000000000012' where person_id='00000000-0000-0000-0000-000000001002'$test$, '42501', null, 'Client cannot relocate membership');
select throws_ok($test$select * from pikas_private.role_capabilities$test$, '42501', null, 'Client cannot read or customize private RBAC catalog');
select throws_ok($test$insert into pikas_private.role_capabilities values ('school','school_admin','pos:checkout')$test$, '42501', null, 'Client cannot grant new capabilities');
reset role;
select set_config('request.jwt.claim.sub', '', true);
grant insert on public.school_memberships to authenticated;
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002002', true);
set local role authenticated;
select throws_ok($test$insert into school_memberships(account_id,school_id,person_id,role_code) values ('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000012','00000000-0000-0000-0000-000000001002','school_admin')$test$, '42501', null, 'RLS denies forged insertion even with temporary SQL INSERT grant');
reset role;
select set_config('request.jwt.claim.sub', '', true);
revoke insert on public.school_memberships from authenticated;
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002003', true);
set local role authenticated;
select is((select count(*) from cafeterias), 1::bigint, 'Cafeteria A1 administrator sees own cafeteria');
select is((select count(*) from cafeterias where id='00000000-0000-0000-0000-000000000112'), 0::bigint, 'Cafeteria A2 denied');
select is((select count(*) from cafeterias where id='00000000-0000-0000-0000-000000000121'), 0::bigint, 'Cross-account cafeteria B1 denied');
select is((select count(*) from schools), 0::bigint, 'Cafeteria admin does not inherit school authority');
select is((select count(*) from school_locations), 1::bigint, 'Cafeteria admin sees only its authorized parent campus');
select ok((not pikas_private.has_capability('cafeteria:read','00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000111')), 'Forged account in authorization helper fails closed');
select is((select count(*) from audit_events where cafeteria_id is null), 0::bigint, 'Cafeteria audit does not expose school/account audit');
select ok((exists(select 1 from audit_events)), 'Cafeteria sees scoped audit evidence');
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002005', true);
set local role authenticated;
select is((select count(*) from schools), 2::bigint, 'Independent legitimate memberships permit A1 and A2');
reset role;
select set_config('request.jwt.claim.sub', '', true);
update school_memberships set status='suspended' where id='00000000-0000-0000-0000-000000003102';
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002005', true);
set local role authenticated;
select is((select count(*) from schools where id='00000000-0000-0000-0000-000000000011'), 0::bigint, 'Suspended membership loses domain access immediately');
select is((select count(*) from schools where id='00000000-0000-0000-0000-000000000012'), 1::bigint, 'Unrelated membership remains usable');
reset role;
select set_config('request.jwt.claim.sub', '', true);
update school_memberships set status='active' where id='00000000-0000-0000-0000-000000003102';
reset role;
select set_config('request.jwt.claim.sub', '', true);
update accounts set status='suspended' where id='00000000-0000-0000-0000-000000000001';
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002005', true);
set local role authenticated;
select is((select count(*) from schools), 0::bigint, 'Account suspension blocks all descendant schools');
reset role;
select set_config('request.jwt.claim.sub', '', true);
update accounts set status='active' where id='00000000-0000-0000-0000-000000000001';
reset role;
select set_config('request.jwt.claim.sub', '', true);
update schools set status='suspended' where id='00000000-0000-0000-0000-000000000011';
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002002', true);
set local role authenticated;
select is((select count(*) from cafeterias), 0::bigint, 'School suspension blocks its cafeteria');
reset role;
select set_config('request.jwt.claim.sub', '', true);
update schools set status='active' where id='00000000-0000-0000-0000-000000000011';
reset role;
select set_config('request.jwt.claim.sub', '', true);
update cafeterias set status='suspended' where id='00000000-0000-0000-0000-000000000111';
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002003', true);
set local role authenticated;
select is((select count(*) from school_locations), 0::bigint, 'Suspended cafeteria cannot authorize parent campus reads');
reset role;
select set_config('request.jwt.claim.sub', '', true);
update cafeterias set status='active' where id='00000000-0000-0000-0000-000000000111';
reset role;
select set_config('request.jwt.claim.sub', '', true);
update school_locations set status='inactive' where id='00000000-0000-0000-0000-000000000211';
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002003', true);
set local role authenticated;
select is((select count(*) from school_locations), 0::bigint, 'Inactive location is not operationally visible');
reset role;
select set_config('request.jwt.claim.sub', '', true);
update school_locations set status='active' where id='00000000-0000-0000-0000-000000000211';
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002009', true);
set local role authenticated;
select is((select count(*) from schools), 0::bigint, 'Globally suspended person has no membership authority');
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002007', true);
set local role authenticated;
select is((select count(*) from cafeterias), 0::bigint, 'Reserved POS membership exposes no operational catalog');
select ok((not pikas_private.has_capability('cafeteria:read','00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000111')), 'Reserved role has no cafeteria-admin capability');
select set_config('request.jwt.claims','{"user_metadata":{"role":"account_admin","isAdmin":true}}',true);
select is((select count(*) from accounts), 0::bigint, 'Forged user-editable metadata grants no account authority');
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002008', true);
set local role authenticated;
select is((select count(*) from schools), 0::bigint, 'Pending invitation grants no school authority');
select is((select count(id) from invitations), 0::bigint, 'Matching invitation email does not authorize invitation enumeration');
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002002', true);
set local role authenticated;
select is((select count(id) from invitations), 1::bigint, 'School admin sees invitation metadata in own scope');
select throws_ok($test$select token_hash from invitations$test$, '42501', null, 'Invitation token hash is not client readable');
select throws_ok($test$update invitations set status='accepted',accepted_person_id='00000000-0000-0000-0000-000000001008',accepted_at=now() where id='00000000-0000-0000-0000-000000004001'$test$, '42501', null, 'Client cannot self-accept or activate invitations');
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002004', true);
set local role authenticated;
select is((select count(id) from invitations), 0::bigint, 'Other cafeteria cannot see school invitation');
reset role;
select set_config('request.jwt.claim.sub', '', true);
select throws_ok($test$insert into cafeterias(account_id,school_id,school_location_id,code,name) values ('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000211','FORGED','Forged')$test$, '23503', null, 'Cafeteria ancestry mismatch rejected by FK');
select throws_ok($test$insert into school_locations(account_id,school_id,code,name) values ('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000011','FORGED','Forged')$test$, '23503', null, 'Location ancestry mismatch rejected by FK');
select throws_ok($test$insert into school_memberships(account_id,school_id,person_id,role_code) values ('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000001008','school_admin')$test$, '23503', null, 'School membership ancestry mismatch rejected');
select throws_ok($test$insert into cafeteria_memberships(account_id,school_id,cafeteria_id,person_id,role_code) values ('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000012','00000000-0000-0000-0000-000000000111','00000000-0000-0000-0000-000000001008','cafeteria_admin')$test$, '23503', null, 'Cafeteria membership ancestry mismatch rejected');
select throws_ok($test$insert into school_memberships(account_id,school_id,person_id,role_code) values ('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000001008','account_admin')$test$, '23503', null, 'Wrong-domain role rejected by catalog FK');
select throws_ok($test$insert into schools(account_id,code,name) values ('00000000-0000-0000-0000-000000000001',' a1 ','Duplicate')$test$, '23505', null, 'School identifiers normalized and unique within account');
select lives_ok($test$insert into schools(account_id,code,name) values ('00000000-0000-0000-0000-000000000002','A1','Different account')$test$,'School identifier may repeat in another account');
select throws_ok($test$insert into persons(auth_user_id,display_name) values ('00000000-0000-0000-0000-000000002002','Duplicate identity')$test$, '23505', null, 'Auth identity links to at most one person');
select throws_ok($test$update persons set id='00000000-0000-0000-0000-000000009999' where id='00000000-0000-0000-0000-000000001008'$test$, '23514', null, 'PIKAS person ID is immutable');
select throws_ok($test$update school_memberships set school_id='00000000-0000-0000-0000-000000000012' where id='00000000-0000-0000-0000-000000003101'$test$, '23514', null, 'Existing membership cannot be reassigned to a new scope');
select throws_ok($test$update accounts set status='deleted' where id='00000000-0000-0000-0000-000000000001'$test$, '23514', null, 'Invalid lifecycle state rejected');
select throws_ok($test$insert into invitations(account_id,school_id,scope_kind,role_code,intended_email,token_hash,invited_by,expires_at) values ('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','account','account_admin','x@example.invalid',repeat('b',64),'00000000-0000-0000-0000-000000001001',now()+interval '1 day')$test$, '23514', null, 'Invitation scope shape must match intended role');
select throws_ok($test$insert into invitations(account_id,school_id,scope_kind,role_code,intended_email,token_hash,invited_by,expires_at) values ('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000011','school','school_admin','x@example.invalid',repeat('b',64),'00000000-0000-0000-0000-000000001001',now()+interval '1 day')$test$, '23503', null, 'Invitation cannot forge tenant ancestry');
select throws_ok($test$update invitations set status='accepted' where id='00000000-0000-0000-0000-000000004001'$test$, '23514', null, 'Accepted invitation requires person and timestamp evidence');
select throws_ok($test$update invitations set expires_at=created_at where id='00000000-0000-0000-0000-000000004001'$test$, '23514', null, 'Invitation expiry must follow creation');
insert into audit_events(actor_person_id,authenticated_user_id,actor_role,actor_scope_kind,account_id,school_id,action,target_type,target_id,outcome) values ('00000000-0000-0000-0000-000000001010','00000000-0000-0000-0000-000000002010','school_admin','school','00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011','synthetic_history','schools','00000000-0000-0000-0000-000000000011','succeeded');
delete from auth.users where id='00000000-0000-0000-0000-000000002010';
select is((select count(*) from persons where id='00000000-0000-0000-0000-000000001010' and auth_user_id is null), 1::bigint, 'Auth removal unlinks rather than deletes person');
select is((select count(*) from school_memberships where person_id='00000000-0000-0000-0000-000000001010'), 1::bigint, 'Auth removal preserves historical membership');
select is((select count(*) from audit_events where actor_person_id='00000000-0000-0000-0000-000000001010' and authenticated_user_id='00000000-0000-0000-0000-000000002010'), 1::bigint, 'Auth removal preserves historical actor and Auth reference');
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002010', true);
set local role authenticated;
select is((select count(*) from schools), 0::bigint, 'Removed Auth linkage cannot retain access with old subject');
reset role;
select set_config('request.jwt.claim.sub', '', true);
select throws_ok($test$delete from persons where id='00000000-0000-0000-0000-000000001010'$test$, '23503', null, 'Referenced historical person cannot be deleted');
select throws_ok($test$update audit_events set action='rewritten'$test$, '23514', null, 'Audit evidence is append-only even for ordinary owner DML');
select throws_ok($test$delete from audit_events$test$, '23514', null, 'Audit events cannot be deleted');
select throws_ok($test$truncate audit_events$test$, '23514', null, 'Audit events cannot be truncated');
select ok((not exists(select 1 from audit_events where before_metadata ?| array['token_hash','intended_email','auth_user_id'] or after_metadata ?| array['token_hash','intended_email','auth_user_id'])), 'Automatic audit omits tokens and unnecessary identity payloads');
reset role;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000002002', true);
set local role authenticated;
select is((select count(*) from audit_events where school_id is distinct from '00000000-0000-0000-0000-000000000011' or cafeteria_id is not null), 0::bigint, 'School audit stays within its peer domain');
select throws_ok($test$insert into audit_events(actor_role,actor_scope_kind,action,target_type,target_id,outcome) values ('account_admin','system','forged','schools','00000000-0000-0000-0000-000000000011','succeeded')$test$, '42501', null, 'Clients cannot forge audit evidence');
reset role;
select set_config('request.jwt.claim.sub', '', true);
set local role anon;
select throws_ok($test$select * from schools$test$, '42501', null, 'Anonymous direct table access denied');
select throws_ok($test$select pikas_private.has_capability('school:read','00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011')$test$, '42501', null, 'Anonymous authorization helper execution denied');
reset role;
select set_config('request.jwt.claim.sub', '', true);
-- Additional boundary and lifecycle evidence under the database owner.
-- Count history: 2 (Phase 1) + 7 platform tables (6A1, stale at HEAD: produced 9) + 3 sandbox POV tables (6B) = 12.
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='pikas_private' and c.relkind='r' and c.relrowsecurity), 12::bigint,
  'Private role catalog also has RLS enabled');
select throws_ok($test$update schools set business_timezone='Not/A_Timezone'
  where id='00000000-0000-0000-0000-000000000011'$test$, '23514', null, 'Invalid business timezone rejected');
select lives_ok($test$insert into persons(id,display_name)
  values ('00000000-0000-0000-0000-000000001099','Synthetic no-login person')$test$,
  'Domain person may exist without any Auth identity');
select throws_ok($test$insert into audit_events(actor_role,actor_scope_kind,account_id,school_id,
  action,target_type,target_id,outcome) values ('database_maintenance','system',
  '00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000011',
  'forged','schools','00000000-0000-0000-0000-000000000011','succeeded')$test$,
  '23503', null, 'Audit ancestry cannot combine another account and school');
select throws_ok($test$update persons set created_at=created_at-interval '1 day'
  where id='00000000-0000-0000-0000-000000001002'$test$, '23514', null,
  'Creation timestamp cannot be rewritten');
select throws_ok($test$insert into school_memberships(account_id,school_id,person_id,role_code)
  values ('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000011',
  '00000000-0000-0000-0000-000000001002','school_admin')$test$, '23505', null,
  'Duplicate person role in the same scope is rejected');
update persons set auth_user_id=null where id='00000000-0000-0000-0000-000000001008';
select is((select count(*) from persons where id='00000000-0000-0000-0000-000000001008'
  and auth_user_id is null),1::bigint,'Explicit Auth unlink preserves person');
update cafeteria_memberships set status='inactive' where id='00000000-0000-0000-0000-000000003201';
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002003',true);
set local role authenticated;
select is((select count(*) from cafeterias),0::bigint,'Inactive membership loses access');
reset role;
select set_config('request.jwt.claim.sub','',true);
update cafeteria_memberships set status='active' where id='00000000-0000-0000-0000-000000003201';
update accounts set status='inactive' where id='00000000-0000-0000-0000-000000000001';
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002006',true);
set local role authenticated;
select is((select count(*) from schools),1::bigint,'Account A deactivation does not affect authorized Account B schools');
reset role;
select set_config('request.jwt.claim.sub','',true);
update accounts set status='active' where id='00000000-0000-0000-0000-000000000001';
-- UPDATE/DELETE RLS remain fail-closed if grants are mistakenly broadened.
grant update, delete on public.school_memberships to authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000002002',true);
set local role authenticated;
with changed as (update school_memberships set status='inactive' returning id)
select is(count(*),0::bigint,'No UPDATE policy even after accidental UPDATE grant') from changed;
with changed as (delete from school_memberships returning id)
select is(count(*),0::bigint,'No DELETE policy even after accidental DELETE grant') from changed;
reset role;
select set_config('request.jwt.claim.sub','',true);
revoke update, delete on public.school_memberships from authenticated;
-- Campus hierarchy and authorization regression coverage.
reset role;
